// Category C: no headless primitive. React Aria ships no window splitter, and its `useMove` lives in
// `react-aria`, a package this one does not declare (component-contract.md §6 rule 3), so the drag
// and the keys are wired here, to the WAI-ARIA APG Window Splitter pattern.
import { useRef, useState } from "react";
import type { CSSProperties, HTMLAttributes, KeyboardEvent, PointerEvent, Ref } from "react";
import "./ResizeHandle.css";

export interface ResizeHandleProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "className" | "onChange" | "role" | "aria-orientation" | "aria-valuenow" | "aria-valuemin" | "aria-valuemax"> {
  /**
   * Which way the handle runs. A `vertical` handle stands between two columns and moves across; a
   * `horizontal` one lies between two rows and moves up and down.
   *
   * @default "vertical"
   */
  orientation?: "vertical" | "horizontal";
  /**
   * Which side of the handle the pane it sizes is on. `start` grows as the handle moves toward the
   * end (a sidebar's trailing edge); `end` grows as it moves toward the start (a right-hand panel's
   * leading edge).
   *
   * @default "start"
   */
  paneSide?: "start" | "end";
  /** The pane's size, in px. */
  value: number;
  /** The smallest size the pane may take, in px. */
  minValue: number;
  /** The largest size the pane may take, in px. */
  maxValue: number;
  /**
   * How far one arrow key moves the handle, in px. Home and End go to `minValue` and `maxValue`.
   *
   * @default 16
   */
  step?: number;
  /** The new size, as the handle is dragged or moved with the keys. */
  onChange: (value: number) => void;
  /** What the handle resizes, which a separator has no text to say ("Sidebar width"). */
  "aria-label": string;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

export function ResizeHandle({
  orientation = "vertical",
  paneSide = "start",
  value,
  minValue,
  maxValue,
  step = 16,
  onChange,
  className,
  ...props
}: ResizeHandleProps) {
  const [hovered, setHovered] = useState(false);
  const drag = useRef<{ at: number; value: number } | null>(null);
  const clamp = (v: number) => Math.min(maxValue, Math.max(minValue, Math.round(v)));
  /* +1 when moving toward the pane's far side grows it. Inline motion follows the writing direction,
     so a right-to-left page reverses a vertical handle's keys and drag. */
  const growth = (el: Element) => {
    const rtl = orientation === "vertical" && getComputedStyle(el).direction === "rtl";
    return (paneSide === "start" ? 1 : -1) * (rtl ? -1 : 1);
  };
  const point = (e: PointerEvent) => (orientation === "vertical" ? e.clientX : e.clientY);

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    e.currentTarget.focus({ preventScroll: true });
    drag.current = { at: point(e), value };
  };
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (d) onChange(clamp(d.value + growth(e.currentTarget) * (point(e) - d.at)));
  };
  const onPointerEnd = () => {
    drag.current = null;
  };
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const toEnd = orientation === "vertical" ? "ArrowRight" : "ArrowDown";
    const toStart = orientation === "vertical" ? "ArrowLeft" : "ArrowUp";
    let next: number | null = null;
    if (e.key === toEnd) next = value + growth(e.currentTarget) * step;
    else if (e.key === toStart) next = value - growth(e.currentTarget) * step;
    else if (e.key === "Home") next = minValue;
    else if (e.key === "End") next = maxValue;
    if (next === null) return;
    e.preventDefault();
    onChange(clamp(next));
  };

  return (
    <div
      {...props}
      role="separator"
      tabIndex={0}
      aria-orientation={orientation}
      aria-valuenow={clamp(value)}
      aria-valuemin={minValue}
      aria-valuemax={maxValue}
      data-orientation={orientation}
      data-hovered={hovered || undefined}
      className={className ? `sd-resize-handle ${className}` : "sd-resize-handle"}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerEnd}
      onPointerCancel={onPointerEnd}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
      onKeyDown={onKeyDown}
    />
  );
}

/* ResizeHandle.css — .sd-resize-handle
   A hit area on the edge between two panes, with the line it exposes drawn in its middle (`::after`),
   as a table column's resizer is. The consumer places it on the edge; it takes no room of its own
   beyond its hit area. Focus is the platform's `:focus-visible`: the element is ours and no React
   Aria primitive emits the state (component-contract.md §6 rule 3). */
.sd-resize-handle {
  position: relative;
  flex: none;
  touch-action: none;
  outline: none;
}
.sd-resize-handle[data-orientation="vertical"] {
  align-self: stretch;
  inline-size: var(--sd-resize-handle-width);
  cursor: col-resize;
}
.sd-resize-handle[data-orientation="horizontal"] {
  block-size: var(--sd-resize-handle-width);
  cursor: row-resize;
}

.sd-resize-handle::after {
  content: "";
  position: absolute;
  background: var(--sd-resize-handle-background);
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-resize-handle[data-orientation="vertical"]::after {
  inset-block: 0;
  inset-inline-start: 50%;
  inline-size: var(--sd-resize-handle-line-width);
  translate: -50%;
}
.sd-resize-handle[data-orientation="horizontal"]::after {
  inset-inline: 0;
  inset-block-start: 50%;
  block-size: var(--sd-resize-handle-line-width);
  translate: 0 -50%;
}

/* Hovered, and so while dragged: the pointer is captured on the handle until it lets go. */
.sd-resize-handle[data-hovered]::after {
  background: var(--sd-resize-handle-background-active);
}

/* Focus thickens the line in the ring colour; the transparent outline is what forced-colors mode
   paints in its place (component-contract.md §6 rule 3). */
.sd-resize-handle:focus-visible {
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-resize-handle[data-orientation="vertical"]:focus-visible::after {
  inline-size: var(--sd-resize-handle-line-width-focus);
  background: color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
}
.sd-resize-handle[data-orientation="horizontal"]:focus-visible::after {
  block-size: var(--sd-resize-handle-line-width-focus);
  background: color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
}

@media (prefers-reduced-motion: reduce) {
  .sd-resize-handle::after {
    transition: none;
  }
}
